1	import {
2	  Membership,
3	  type RoomInterface,
4	  type RoomListEntriesUpdate,
5	  RoomListEntriesUpdate_Tags,
6	  type RoomListEntriesWithDynamicAdaptersResultInterface,
7	  type RoomListInterface,
8	  RoomListServiceState,
9	  type TaskHandleInterface,
10	} from "@unomed/react-native-matrix-sdk";
11	import { useAtomValue, useSetAtom } from "jotai";
12	import { AuthService } from "modules/auth/service/AuthService";
13	import { useEffect, useRef } from "react";
14	import Toast from "react-native-toast-message";
15	import { MatrixJotaiStore } from "../const/matrx-jotai-store";
16	import { MatrixAtoms } from "../jotai";
17	import { MatrixCore } from "../services/MatrixCore";
18	
19	const MAX_SYNC_RETRIES = 3;
20	
21	export const RoomListProvider = () => {
22	  const client = useAtomValue(MatrixAtoms.matrixClient);
23	  const syncService = useAtomValue(MatrixAtoms.syncService);
24	  const setIsLoading = useSetAtom(MatrixAtoms.roomListLoading);
25	
26	  // Unfiltered rooms matching the SDK's index space — required for correct diff application
27	  const roomsRef = useRef<RoomInterface[]>([]);
28	  const hasShownInitialSyncToast = useRef(false);
29	
30	  const roomListRef = useRef<RoomListInterface | null>(null);
31	  const entriesResultRef =
32	    useRef<RoomListEntriesWithDynamicAdaptersResultInterface | null>(null);
33	  const retryCountRef = useRef(0);
34	
35	  useEffect(() => {
36	    if (!client || !syncService) return;
37	
38	    let streamHandle: TaskHandleInterface | null = null;
39	    let stateHandle: TaskHandleInterface | null = null;
40	
41	    const applyDiffsAndPublish = (
42	      updates: RoomListEntriesUpdate[],
43	    ): RoomInterface[] => {
44	      const rooms = [...roomsRef.current];
45	
46	      for (const update of updates) {
47	        switch (update.tag) {
48	          case RoomListEntriesUpdate_Tags.Reset:
49	            rooms.splice(0, rooms.length, ...update.inner.values);
50	            break;
51	          case RoomListEntriesUpdate_Tags.Append:
52	            rooms.push(...update.inner.values);
53	            break;
54	          case RoomListEntriesUpdate_Tags.Clear:
55	            rooms.splice(0, rooms.length);
56	            break;
57	          case RoomListEntriesUpdate_Tags.Insert:
58	            rooms.splice(update.inner.index, 0, update.inner.value);
59	            break;
60	          case RoomListEntriesUpdate_Tags.Set:
61	            rooms[update.inner.index] = update.inner.value;
62	            break;
63	          case RoomListEntriesUpdate_Tags.Remove:
64	            rooms.splice(update.inner.index, 1);
65	            break;
66	          case RoomListEntriesUpdate_Tags.PushFront:
67	            rooms.unshift(update.inner.value);
68	            break;
69	          case RoomListEntriesUpdate_Tags.PushBack:
70	            rooms.push(update.inner.value);
71	            break;
72	          case RoomListEntriesUpdate_Tags.PopFront:
73	            rooms.shift();
74	            break;
75	          case RoomListEntriesUpdate_Tags.PopBack:
76	            rooms.pop();
77	            break;
78	          case RoomListEntriesUpdate_Tags.Truncate:
79	            rooms.splice(update.inner.length);
80	            break;
81	        }
82	      }
83	
84	      roomsRef.current = rooms;
85	
86	      const filtered = rooms.filter((room) => {
87	        const m = room.membership();
88	        return (
89	          m !== Membership.Banned &&
90	          m !== Membership.Left &&
91	          m !== Membership.Knocked
92	        );
93	      });
94	
95	      MatrixJotaiStore.set(MatrixAtoms.roomList, filtered);
96	      return filtered;
97	    };
98	
99	    const updateRoomInfoForDiffs = async (updates: RoomListEntriesUpdate[]) => {
100	      const addedOrUpdated = updates.flatMap((u) => {
101	        switch (u.tag) {
102	          case RoomListEntriesUpdate_Tags.Reset:
103	            return u.inner.values;
104	          case RoomListEntriesUpdate_Tags.Append:
105	            return u.inner.values;
106	          case RoomListEntriesUpdate_Tags.Insert:
107	            return [u.inner.value];
108	          case RoomListEntriesUpdate_Tags.Set:
109	            return [u.inner.value];
110	          case RoomListEntriesUpdate_Tags.PushFront:
111	            return [u.inner.value];
112	          case RoomListEntriesUpdate_Tags.PushBack:
113	            return [u.inner.value];
114	          default:
115	            return [];
116	        }
117	      });
118	
119	      if (addedOrUpdated.length === 0) return;
120	
121	      const currentMap = MatrixJotaiStore.get(MatrixAtoms.roomInfoMap);
122	      const newMap = new Map(currentMap);
123	
124	      await Promise.allSettled(
125	        addedOrUpdated.map(async (room: RoomInterface) => {
126	          try {
127	            const info = await room.roomInfo();
128	            newMap.set(room.id(), info);
129	          } catch {
130	            // ignore per-room failures
131	          }
132	        }),
133	      );
134	
135	      MatrixJotaiStore.set(MatrixAtoms.roomInfoMap, newMap);
136	    };
137	
138	    const init = async () => {
139	      try {
140	        const roomListService = syncService.roomListService();
141	        if (!roomListService) return;
142	
143	        roomListRef.current = await roomListService.allRooms();
144	
145	        // Listener stored at module scope to prevent GC — onUpdate must be synchronous
146	        entriesResultRef.current =
147	          roomListRef.current.entriesWithDynamicAdaptersWith(500, true, {
148	            onUpdate: (updates) => {
149	              // Sync update — no await here
150	              applyDiffsAndPublish(updates);
151	              // Fire-and-forget async room info
152	              updateRoomInfoForDiffs(updates).catch(console.warn);
153	            },
154	          });
155	
156	        streamHandle = entriesResultRef.current.entriesStream();
157	
158	        // State listener — fallback refresh + loading indicator
159	        stateHandle = roomListService.state({
160	          onUpdate: (state: RoomListServiceState) => {
161	            if (
162	              state === RoomListServiceState.SettingUp ||
163	              state === RoomListServiceState.Recovering
164	            ) {
165	              setIsLoading(true);
166	              if (!hasShownInitialSyncToast.current) {
167	                hasShownInitialSyncToast.current = true;
168	                Toast.show({
169	                  type: "loading",
170	                  text1: "Syncing rooms...",
171	                  autoHide: false,
172	                });
173	              }
174	            }
175	
176	            if (state === RoomListServiceState.Running) {
177	              retryCountRef.current = 0;
178	              // Fallback: refresh from client in case subscription missed any diffs
179	              MatrixCore.refreshRoomList().then(() => {
180	                setIsLoading(false);
181	                Toast.hide();
182	              });
183	            }
184	
185	            if (state === RoomListServiceState.Error) {
186	              if (retryCountRef.current < MAX_SYNC_RETRIES) {
187	                retryCountRef.current += 1;
188	                setTimeout(() => AuthService.startSync(), 2000);
189	              } else {
190	                setIsLoading(false);
191	                Toast.show({
192	                  type: "error",
193	                  text1: "Sync failed. Please restart the app.",
194	                  autoHide: false,
195	                });
196	              }
197	            }
198	          },
199	        });
200	      } catch (error) {
201	        console.error("[RoomListProvider] init failed:", error);
202	      } finally {
203	        setIsLoading(false);
204	      }
205	    };
206	
207	    init();
208	
209	    return () => {
210	      streamHandle?.cancel?.();
211	      stateHandle?.cancel?.();
212	      roomsRef.current = [];
213	      roomListRef.current = null;
214	      entriesResultRef.current = null;
215	    };
216	  }, [client, syncService]);
217	
218	  return <></>;
219	};
