26	const roomList = atom<RoomInterface[]>([]);
27	
28	const roomInfoMap = atom<Map<string, RoomInfo>>(new Map());
29	
30	const roomListLoading = atom<boolean>(true);
31	
32	const matrixClient = atom<ClientInterface | null>(null);
33	
34	const syncService = atom<SyncServiceInterface | null>(null);
35	
36	const ignoredUsers = atom<string[] | null>(null);
37	
38	const verificationStatus = atom<VerificationStatus>("idle");
