45	  roomList,
46	  roomInfoMap,
47	  roomListLoading,
48	  matrixClient,
49	  syncService,
50	  ignoredUsers,
51	  verificationStatus,
52	  verificationEmojis,
53	  verificationSenderName,
54	};
55	
56	export const resetMatrixAtoms = () => {
57	  MatrixJotaiStore.set(roomList, []);
58	  MatrixJotaiStore.set(roomInfoMap, new Map());
