60	  MatrixJotaiStore.set(matrixClient, null);
61	  MatrixJotaiStore.set(syncService, null);
62	  MatrixJotaiStore.set(ignoredUsers, null);
63	  MatrixJotaiStore.set(verificationStatus, "idle");
64	  MatrixJotaiStore.set(verificationEmojis, null);
65	  MatrixJotaiStore.set(verificationSenderName, null);
66	};
