1	import {
2	  AuthData,
3	  AuthDataPasswordDetails,
4	  BackupDownloadStrategy,
5	  ClientBuilder,
6	  type Session,
7	  SlidingSyncVersion,
8	  SlidingSyncVersionBuilder,
9	} from "@unomed/react-native-matrix-sdk";
10	import { StorageAtoms } from "modules/storage/jotai/atoms";
11	import { deleteJotaiStorageAdapter } from "modules/storage/utils";
12	import RNFS from "react-native-fs";
13	import { clearEncryptedImageCache } from "shared/utils/encrypted-image-cache";
14	import { clearEncryptedVideoCache } from "shared/utils/encrypted-video-cache";
15	import { clearImageCache } from "shared/utils/image-caching";
16	import { clearMediaEncryptionKey } from "shared/utils/media-encryption";
17	import { MatrixStorage } from "../../matrix-client/const";
18	import { MatrixJotaiStore } from "../../matrix-client/const/matrx-jotai-store";
19	import { MatrixAtoms, resetMatrixAtoms } from "../../matrix-client/jotai";
20	import { MatrixCore } from "../../matrix-client/services/MatrixCore";
21	import { PushNotificationsAtoms } from "../../push-notifications/jotai";
22	import { MatrixNotificationService } from "../../push-notifications/service/MatrixNotificationService";
23	
24	type LoginWithUsernameAndPasswordData = {
25	  username: string;
26	  password: string;
27	};
28	
29	const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
30	const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;
31	
32	export class AuthService {
33	  private static async clearCryptoStore() {
34	    try {
35	      const dataExists = await RNFS.exists(dataPath);
36	      const cacheExists = await RNFS.exists(cachePath);
37	
38	      if (dataExists) {
39	        await RNFS.unlink(dataPath);
40	        console.log("Cleared crypto data store");
41	      }
42	
43	      if (cacheExists) {
44	        await RNFS.unlink(cachePath);
45	        console.log("Cleared crypto cache store");
46	      }
47	    } catch (error) {
48	      console.warn("Failed to clear crypto store:", error);
49	    }
50	  }
51	
52	  /** Full init for first login — does server discovery (requires network). */
53	  public static initialize = async (serverUrl: string) => {
54	    MatrixCore.instance = await new ClientBuilder()
55	      .serverNameOrHomeserverUrl(serverUrl)
56	      .sessionPaths(dataPath, cachePath)
57	      .autoEnableCrossSigning(true)
58	      .autoEnableBackups(false)
59	      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
60	      .build();
61	  };
62	
63	  /**
64	   * Offline-capable init for session restore.
65	   * Uses the exact homeserver URL + known username so no server discovery is needed.
66	   */
67	  private static initializeForRestore = async (
68	    homeserverUrl: string,
69	    userId: string,
70	  ) => {
71	    MatrixCore.instance = await new ClientBuilder()
72	      .homeserverUrl(homeserverUrl)
73	      .username(userId)
74	      .slidingSyncVersionBuilder(SlidingSyncVersionBuilder.Native)
75	      .sessionPaths(dataPath, cachePath)
76	      .autoEnableCrossSigning(true)
77	      .autoEnableBackups(false)
78	      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
79	      .build();
80	  };
81	
82	  public static hasStoredCredentials = (): boolean => {
83	    return MatrixStorage.hasStoredCredentials();
84	  };
85	
86	  public static getServerName = () => MatrixCore.getServerName();
87	
88	  public static getUser = () => {
89	    if (!MatrixCore.instance) return null;
90	    const userId = MatrixCore.instance.userId();
91	    return userId ? MatrixCore.instance.getProfile(userId) : null;
92	  };
93	
94	  public static restoreSessionForBackground = async (): Promise<boolean> => {
95	    try {
96	      if (
97	        MatrixCore.instance &&
98	        MatrixNotificationService.getNotificationClient()
99	      )
100	        return true;
101	
102	      const credentials = MatrixStorage.getLoginCredentials();
103	      if (!credentials) return false;
104	
105	      // Use the same offline-safe init as foreground so the client is compatible
106	      // if the foreground reuses this instance (same file paths, same sync config).
107	      await this.initializeForRestore(credentials.baseUrl, credentials.userId);
108	
109	      const client = MatrixCore.getClient();
110	
111	      await client.restoreSession({
112	        accessToken: credentials.accessToken,
113	        refreshToken: credentials.refreshToken,
114	        userId: credentials.userId,
115	        deviceId: credentials.deviceId,
116	        homeserverUrl: credentials.baseUrl,
117	        oidcData: undefined,
118	        slidingSyncVersion: SlidingSyncVersion.Native,
119	      });
120	
121	      await client.encryption().waitForE2eeInitializationTasks();
122	
123	      await MatrixNotificationService.ensureNotificationClient();
124	
125	      return true;
126	    } catch (error) {
127	      console.error("[Background] Failed to restore session:", error);
128	      return false;
129	    }
130	  };
131	
132	  public static restoreSession = async (): Promise<boolean> => {
133	    try {
134	      const credentials = MatrixStorage.getLoginCredentials();
135	      if (!credentials) return false;
136	
137	      // If the background handler already initialized and restored the client,
138	      // reuse it — creating a second client on the same file paths would
139	      // conflict with the existing native SDK file locks and cause a hang.
140	      if (!MatrixCore.instance) {
141	        // Use offline-capable init: direct homeserver URL + known username,
142	        // no server discovery needed.
143	        await this.initializeForRestore(
144	          credentials.baseUrl,
145	          credentials.userId,
146	        );
147	
148	        const client = MatrixCore.getClient();
149	
150	        await client.restoreSession({
151	          accessToken: credentials.accessToken,
152	          refreshToken: credentials.refreshToken,
153	          userId: credentials.userId,
154	          deviceId: credentials.deviceId,
155	          homeserverUrl: credentials.baseUrl,
156	          oidcData: undefined,
157	          slidingSyncVersion: SlidingSyncVersion.Native,
158	        });
159	      }
160	
161	      const client = MatrixCore.getClient();
162	
163	      // Profile fetch may fail when offline — don't block session restore on it.
164	      try {
165	        const profile = await client.getProfile(credentials.userId);
166	        MatrixJotaiStore.set(StorageAtoms.cachedProfile, profile);
167	      } catch {}
168	
169	      // withOfflineMode() serves cached rooms immediately without waiting for network.
170	      MatrixCore.syncService = await client
171	        .syncService()
172	        .withOfflineMode()
173	        .finish();
174	
175	      if (!MatrixCore.syncService) {
176	        throw new Error("Failed to initialize sync service");
177	      }
178	
179	      MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
180	      MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
181	
182	      return true;
183	    } catch (error) {
184	      console.warn("Failed to restore session:", error);
185	
186	      MatrixCore.instance = null;
187	      MatrixCore.syncService = null;
188	
189	      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
190	      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
191	
192	      return false;
193	    }
194	  };
195	
196	  /** Start (or resume) the Matrix sync loop. No-op if the sync service is not ready. */
197	  public static startSync = async (): Promise<void> => {
198	    if (!MatrixCore.syncService) return;
199	    try {
200	      await MatrixCore.syncService.start();
201	    } catch (error) {
202	      console.warn("Failed to start sync:", error);
203	    }
204	  };
205	
206	  /** Stop the Matrix sync loop. No-op if the sync service is not ready. */
207	  public static stopSync = async (): Promise<void> => {
208	    if (!MatrixCore.syncService) return;
209	    try {
210	      await MatrixCore.syncService.stop();
211	    } catch (error) {
212	      console.warn("Failed to stop sync:", error);
213	    }
214	  };
215	
216	  public static setup = async (params: Session) => {
217	    await this.clearCryptoStore();
218	
219	    if (MatrixCore.syncService) await MatrixCore.syncService.stop();
220	    MatrixCore.instance = null;
221	    MatrixCore.syncService = null;
222	
223	    MatrixStorage.saveLoginCredentials({
224	      accessToken: params.accessToken,
225	      refreshToken: params.refreshToken,
226	      userId: params.userId,
227	      deviceId: params.deviceId,
228	      baseUrl: params.homeserverUrl,
229	    });
230	
231	    await this.initialize(params.homeserverUrl);
232	
233	    const client = MatrixCore.getClient();
234	
235	    await client.restoreSession({
236	      accessToken: params.accessToken,
237	      refreshToken: params.refreshToken,
238	      userId: params.userId,
239	      deviceId: params.deviceId,
240	      homeserverUrl: params.homeserverUrl,
241	      oidcData: undefined,
242	      slidingSyncVersion: SlidingSyncVersion.Native,
243	    });
244	
245	    try {
246	      const profile = await client.getProfile(params.userId);
247	      MatrixJotaiStore.set(StorageAtoms.cachedProfile, profile);
248	    } catch (error) {
249	      console.warn("Session validation failed:", error);
250	    }
251	
252	    MatrixCore.syncService = await client.syncService().finish();
253	
254	    if (!MatrixCore.syncService) {
255	      throw new Error("Failed to initialize sync service");
256	    }
257	
258	    await MatrixCore.syncService.start();
259	    await client.encryption().waitForE2eeInitializationTasks();
260	
261	    MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
262	    MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
263	  };
264	
265	  public static login = async ({
266	    username,
267	    password,
268	  }: LoginWithUsernameAndPasswordData) => {
269	    const client = MatrixCore.getClient();
270	    await client.login(username, password, undefined, undefined);
271	    const session = client.session();
272	
273	    MatrixCore.instance = null;
274	
275	    return session;
276	  };
277	
278	  public static logout = async () => {
279	    // Remove pusher before clearing the session — needs an active Matrix client.
280	    // Ignore errors (user may be offline or permissions already revoked).
281	    const fcmToken = MatrixJotaiStore.get(PushNotificationsAtoms.token);
282	    if (fcmToken) {
283	      try {
284	        await MatrixNotificationService.removePusher(fcmToken);
285	      } catch {}
286	    }
287	
288	    MatrixStorage.clearLoginCredentials();
289	    deleteJotaiStorageAdapter();
290	    await this.clearCryptoStore();
291	    await clearImageCache();
292	    await clearEncryptedImageCache();
293	    await clearEncryptedVideoCache();
294	    await clearMediaEncryptionKey();
295	
296	    //Ignore both errors if it happens, the logout will still happen. These errors can happen if the user is offline.
297	    if (MatrixCore.syncService) {
298	      try {
299	        await MatrixCore.syncService.stop();
300	      } catch {}
301	    }
302	    if (MatrixCore.instance) {
303	      try {
304	        await MatrixCore.instance.logout();
305	      } catch {}
306	    }
307	
308	    MatrixCore.instance = null;
309	    MatrixCore.syncService = null;
310	
311	    resetMatrixAtoms();
312	  };
313	
314	  public static canDeactivateAccount = (): boolean => {
315	    if (!MatrixCore.instance) return false;
316	    return MatrixCore.instance.canDeactivateAccount();
317	  };
318	
319	  public static deactivateAccount = async (
320	    password: string,
321	    eraseData: boolean,
322	  ) => {
323	    const client = MatrixCore.getClient();
324	
325	    // Step 1: attempt with no auth data. SSO / servers that don't require UIA
326	    // will succeed here. Return immediately — password is not needed.
327	    try {
328	      await client.deactivateAccount(undefined, eraseData);
329	      await this.logout();
330	      return;
331	    } catch {
332	      // Password-based server rejected the unauthenticated attempt. Fall through.
333	    }
334	
335	    // Step 2: authenticate with the user-entered password.
336	    const userId = client.userId();
337	    if (!userId) throw new Error("User ID not found");
338	
339	    const authData = new AuthData.Password({
340	      passwordDetails: AuthDataPasswordDetails.create({
341	        identifier: userId,
342	        password,
343	      }),
344	    });
345	
346	    await client.deactivateAccount(authData, eraseData);
347	    await this.logout();
348	  };
349	}
