1	import { useAtomValue } from "jotai";
2	import { AuthService } from "modules/auth/service/AuthService";
3	import { MatrixAtoms } from "modules/matrix-client/jotai";
4	import { NetworkAtoms } from "modules/network/jotai";
5	import { type FC, useEffect, useRef } from "react";
6	import { AppState, type AppStateStatus } from "react-native";
7	
8	// How long sync keeps running after the app goes to the background
9	// before we stop it. iOS typically gives ~30s of background execution.
10	const BACKGROUND_SYNC_TIMEOUT_MS = 25_000;
11	
12	export const SyncLifecycleProvider: FC = () => {
13	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
14	  const syncService = useAtomValue(MatrixAtoms.syncService);
15	  const prevIsOfflineRef = useRef<boolean | null>(null);
16	  const stopSyncTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
17	
18	  // Start sync whenever a session is restored and sync service becomes available.
19	  // This covers launch paths that skip Splash's explicit startSync call (e.g. PIN screen).
20	  useEffect(() => {
21	    if (!syncService || !isOffline || AppState.currentState !== "active") {
22	      return;
23	    }
24	    AuthService.startSync();
25	  }, [syncService, isOffline, AppState.currentState]);
26	
27	  // Network recovery: restart sync when coming back online
28	  useEffect(() => {
29	    if (prevIsOfflineRef.current === true && !isOffline) {
30	      AuthService.startSync();
31	    }
32	    prevIsOfflineRef.current = isOffline;
33	  }, [isOffline]);
34	
35	  // AppState lifecycle: start sync on foreground, stop after background grace period
36	  useEffect(() => {
37	    const handleAppStateChange = (nextState: AppStateStatus) => {
38	      if (nextState === "active") {
39	        if (stopSyncTimerRef.current) {
40	          clearTimeout(stopSyncTimerRef.current);
41	          stopSyncTimerRef.current = null;
42	        }
43	        AuthService.startSync();
44	      } else if (nextState === "background") {
45	        stopSyncTimerRef.current = setTimeout(() => {
46	          AuthService.stopSync();
47	          stopSyncTimerRef.current = null;
48	        }, BACKGROUND_SYNC_TIMEOUT_MS);
49	      }
50	    };
51	
52	    const subscription = AppState.addEventListener(
53	      "change",
54	      handleAppStateChange,
55	    );
56	
57	    return () => {
58	      subscription.remove();
59	      if (stopSyncTimerRef.current) {
60	        clearTimeout(stopSyncTimerRef.current);
61	      }
62	    };
63	  }, []);
64	
65	  return <></>;
66	};
