1	import {
2	  type ClientInterface,
3	  Membership,
4	  type RoomInfo,
5	  type RoomInterface,
6	  type SyncServiceInterface,
7	} from "@unomed/react-native-matrix-sdk";
8	import { MatrixJotaiStore } from "../const/matrx-jotai-store";
9	import { MatrixAtoms } from "../jotai";
10	
11	export class MatrixCore {
12	  public static instance: ClientInterface | null = null;
13	  public static syncService: SyncServiceInterface | null = null;
14	
15	  /** Returns the client or throws if not initialized. Eliminates per-method null checks. */
16	  public static getClient(): ClientInterface {
17	    if (!MatrixCore.instance) {
18	      throw new Error("Matrix client is not initialized");
19	    }
20	    return MatrixCore.instance;
21	  }
22	
23	  /** Returns the room or throws. Use instead of getClient().getRoom() + manual null check. */
24	  public static getRoom(roomId: string): RoomInterface {
25	    const room = MatrixCore.getClient().getRoom(roomId);
26	    if (!room) throw new Error(`Room not found: ${roomId}`);
27	    return room;
28	  }
29	
30	  public static getServerName = () => {
31	    if (!MatrixCore.instance) return null;
32	    return MatrixCore.instance.server() || MatrixCore.instance.homeserver();
33	  };
34	
35	  /** Sort and store the current room list into Jotai. Called after any membership change. */
36	  public static refreshRoomList = async () => {
37	    if (!MatrixCore.instance) return;
38	
39	    try {
40	      const rooms = MatrixCore.instance.rooms();
41	
42	      const sortedRooms = await Promise.all(
43	        rooms.map(async (room) => ({
44	          room,
45	          timestamp: (await room.latestEvent())?.timestamp || 0,
46	        })),
47	      );
48	
49	      const filteredAndSortedRooms = sortedRooms
50	        .filter(({ room }) => {
51	          const membership = room.membership();
52	          return (
53	            membership !== Membership.Banned &&
54	            membership !== Membership.Left &&
55	            membership !== Membership.Knocked
56	          );
57	        })
58	        .sort((a, b) => {
59	          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
60	          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
61	          if (aInvited !== bInvited) return bInvited - aInvited;
62	          return Number(b.timestamp) - Number(a.timestamp);
63	        });
64	
65	      MatrixJotaiStore.set(
66	        MatrixAtoms.roomList,
67	        filteredAndSortedRooms.map(({ room }) => room),
68	      );
69	
70	      const roomInfoEntries = await Promise.allSettled(
71	        filteredAndSortedRooms.map(async ({ room }) => ({
72	          id: room.id(),
73	          info: await room.roomInfo(),
74	        })),
75	      );
76	
77	      const map = new Map<string, RoomInfo>();
78	      for (const result of roomInfoEntries) {
79	        if (result.status === "fulfilled") {
80	          map.set(result.value.id, result.value.info);
81	        }
82	      }
83	      MatrixJotaiStore.set(MatrixAtoms.roomInfoMap, map);
84	    } catch (error) {
85	      console.error("Failed to refresh room list:", error);
86	    }
87	  };
88	}
